import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import forge from 'node-forge';

export const FIXTURES = path.join(import.meta.dirname, 'fixtures');

// --- Certificates (node-forge; RSA keys generated by Node for speed) ---------------------------

function forgeKeyPair(): {
  privateKey: forge.pki.rsa.PrivateKey;
  publicKey: forge.pki.rsa.PublicKey;
} {
  const { privateKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
  const pem = privateKey.export({ type: 'pkcs1', format: 'pem' }).toString();
  const forgeKey = forge.pki.privateKeyFromPem(pem) as forge.pki.rsa.PrivateKey;
  return { privateKey: forgeKey, publicKey: forge.pki.setRsaPublicKey(forgeKey.n, forgeKey.e) };
}

function makeCert(opts: {
  subject: string;
  publicKey: forge.pki.PublicKey;
  signer: forge.pki.rsa.PrivateKey;
  issuer?: forge.pki.Certificate;
  ca?: boolean;
  serverHosts?: string[];
  clientAuth?: boolean;
}): forge.pki.Certificate {
  const cert = forge.pki.createCertificate();
  cert.publicKey = opts.publicKey;
  cert.serialNumber = `0${crypto.randomBytes(8).toString('hex')}`;
  cert.validity.notBefore = new Date(Date.now() - 24 * 3600 * 1000);
  cert.validity.notAfter = new Date(Date.now() + 365 * 24 * 3600 * 1000);
  const attrs = [
    { name: 'countryName', value: 'ES' },
    { name: 'commonName', value: opts.subject },
  ];
  cert.setSubject(attrs);
  cert.setIssuer(opts.issuer ? opts.issuer.subject.attributes : attrs);
  const extensions: object[] = [{ name: 'basicConstraints', cA: !!opts.ca, critical: true }];
  if (opts.ca)
    extensions.push({ name: 'keyUsage', keyCertSign: true, cRLSign: true, critical: true });
  if (opts.serverHosts) {
    extensions.push({ name: 'extKeyUsage', serverAuth: true });
    extensions.push({
      name: 'subjectAltName',
      altNames: opts.serverHosts.map((h) =>
        /^\d+\.\d+\.\d+\.\d+$/.test(h) ? { type: 7, ip: h } : { type: 2, value: h },
      ),
    });
  }
  if (opts.clientAuth) {
    extensions.push({ name: 'keyUsage', digitalSignature: true, keyEncipherment: true });
    extensions.push({ name: 'extKeyUsage', clientAuth: true });
  }
  cert.setExtensions(extensions);
  cert.sign(opts.signer, forge.md.sha256.create());
  return cert;
}

export interface TestPki {
  caPem: string;
  server: { key: string; cert: string };
  client: { subject: string; p12Aes: Buffer; passphrase: string };
}

/** Test CA, a server certificate for localhost/127.0.0.1 and a client certificate (.p12). */
export function makePki(clientSubject = 'PRUEBA RSA - 99999999R'): TestPki {
  const caKeys = forgeKeyPair();
  const ca = makeCert({
    subject: 'SA TEST CA',
    publicKey: caKeys.publicKey,
    signer: caKeys.privateKey,
    ca: true,
  });
  const serverKeys = forgeKeyPair();
  const server = makeCert({
    subject: 'localhost',
    publicKey: serverKeys.publicKey,
    signer: caKeys.privateKey,
    issuer: ca,
    serverHosts: ['localhost', '127.0.0.1'],
  });
  const clientKeys = forgeKeyPair();
  const client = makeCert({
    subject: clientSubject,
    publicKey: clientKeys.publicKey,
    signer: caKeys.privateKey,
    issuer: ca,
    clientAuth: true,
  });
  // ASCII on purpose: node-forge derives PBES2 (AES) keys from Latin-1 bytes while OpenSSL uses
  // UTF-8, so forge-made AES files with non-ASCII passwords are unreadable elsewhere (@sa/signer's
  // p12 tests cover real files with non-ASCII passwords).
  const passphrase = 'clave-prueba-1';
  const p12Aes = Buffer.from(
    forge.asn1
      .toDer(
        forge.pkcs12.toPkcs12Asn1(clientKeys.privateKey, [client, ca], passphrase, {
          algorithm: 'aes256',
        }),
      )
      .getBytes(),
    'binary',
  );
  return {
    caPem: forge.pki.certificateToPem(ca),
    server: {
      key: forge.pki.privateKeyToPem(serverKeys.privateKey),
      cert: forge.pki.certificateToPem(server),
    },
    client: { subject: clientSubject, p12Aes, passphrase },
  };
}

export function fixtureCert(name: string): Buffer {
  return fs.readFileSync(path.join(FIXTURES, 'certs', name));
}
